import React, { useState } from 'react';

const CATEGORIES = ['Personal', 'Work', 'Home', 'Freelance'];
const PRIORITIES = ['Low', 'Medium', 'High'];
const PRIORITY_SCORE = { 'High': 3, 'Medium': 2, 'Low': 1 };

function getScore(task) {
  if (task.completed) return Infinity;
  const priorityScore = PRIORITY_SCORE[task.priority] || 1;
  const dueScore = task.dueDate
    ? 1 / (Math.max(1, (new Date(task.dueDate) - new Date()) / 86400000))
    : 0;
  return -(priorityScore * 10 + dueScore * 5);
}

function formatDate(dateStr) {
  if (!dateStr) return null;
  const date = new Date(dateStr + 'T00:00:00');
  const today = new Date();
  const tomorrow = new Date();
  tomorrow.setDate(today.getDate() + 1);
  if (date.toDateString() === today.toDateString()) return 'Today';
  if (date.toDateString() === tomorrow.toDateString()) return 'Tomorrow';
  return date.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
}

function isToday(dateStr) {
  if (!dateStr) return false;
  return new Date(dateStr + 'T00:00:00').toDateString() === new Date().toDateString();
}

function isUpcoming(dateStr) {
  if (!dateStr) return false;
  const date = new Date(dateStr + 'T00:00:00');
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  return date > today;
}

const emptyForm = {
  title: '',
  notes: '',
  dueDate: '',
  priority: 'Medium',
  category: 'Personal',
};

function Tasks({ tasks, setTasks }) {
  const [filter, setFilter] = useState('All');
  const [categoryFilter, setCategoryFilter] = useState('All');
  const [showModal, setShowModal] = useState(false);
  const [form, setForm] = useState(emptyForm);
  const [editingId, setEditingId] = useState(null);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(null);

  const sorted = [...tasks].sort((a, b) => getScore(a) - getScore(b));

  const filtered = sorted.filter(task => {
    const statusMatch =
      filter === 'All' ? true :
      filter === 'Today' ? isToday(task.dueDate) && !task.completed :
      filter === 'Upcoming' ? isUpcoming(task.dueDate) && !task.completed :
      filter === 'Completed' ? task.completed : true;
    const catMatch = categoryFilter === 'All' || task.category === categoryFilter;
    return statusMatch && catMatch;
  });

  function openCreate() {
    setForm(emptyForm);
    setEditingId(null);
    setShowModal(true);
  }

  function openEdit(task) {
    setForm({
      title: task.title,
      notes: task.notes || '',
      dueDate: task.dueDate || '',
      priority: task.priority,
      category: task.category,
    });
    setEditingId(task.id);
    setShowModal(true);
  }

  function saveTask() {
    if (!form.title.trim()) return;
    if (editingId) {
      setTasks(tasks.map(t => t.id === editingId ? { ...t, ...form } : t));
    } else {
      setTasks([...tasks, { ...form, id: Date.now(), completed: false, createdAt: new Date().toISOString() }]);
    }
    setShowModal(false);
  }

  function toggleComplete(id) {
    setTasks(tasks.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
  }

  function deleteTask(id) {
    setTasks(tasks.filter(t => t.id !== id));
    setShowDeleteConfirm(null);
  }

  const priorityColor = { High: '#B85C5C', Medium: '#A0856C', Low: '#7A9E87' };

  return (
    <div style={{ padding: '32px 24px 24px', minHeight: '100vh', backgroundColor: 'var(--bg)' }}>

      {/* Header */}
      <p style={{ color: 'var(--text-secondary)', fontSize: '13px', letterSpacing: '0.1em' }}>MANAGE</p>
      <h1 style={{ fontSize: '28px', fontWeight: '300', marginTop: '4px', marginBottom: '24px' }}>Tasks</h1>

      {/* Status filter pills */}
      <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', marginBottom: '12px' }}>
        {['All', 'Today', 'Upcoming', 'Completed'].map(f => (
          <button key={f} onClick={() => setFilter(f)} style={{
            padding: '6px 14px',
            borderRadius: '20px',
            border: '1px solid',
            borderColor: filter === f ? 'var(--accent)' : 'var(--border)',
            backgroundColor: filter === f ? 'var(--accent)' : 'transparent',
            color: filter === f ? 'var(--white)' : 'var(--text-secondary)',
            fontSize: '12px',
            fontFamily: 'Jost, sans-serif',
            fontWeight: '500',
            letterSpacing: '0.05em',
            cursor: 'pointer',
          }}>{f.toUpperCase()}</button>
        ))}
      </div>

      {/* Category filter pills */}
      <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', marginBottom: '24px' }}>
        {['All', ...CATEGORIES].map(c => (
          <button key={c} onClick={() => setCategoryFilter(c)} style={{
            padding: '4px 12px',
            borderRadius: '20px',
            border: '1px solid',
            borderColor: categoryFilter === c ? 'var(--text-primary)' : 'var(--border)',
            backgroundColor: categoryFilter === c ? 'var(--text-primary)' : 'transparent',
            color: categoryFilter === c ? 'var(--white)' : 'var(--text-secondary)',
            fontSize: '11px',
            fontFamily: 'Jost, sans-serif',
            fontWeight: '400',
            cursor: 'pointer',
          }}>{c}</button>
        ))}
      </div>

      {/* Task list */}
      {filtered.length === 0 ? (
        <div style={{ textAlign: 'center', marginTop: '60px', color: 'var(--text-secondary)' }}>
          <p style={{ fontSize: '32px', marginBottom: '12px' }}>✓</p>
          <p style={{ fontSize: '14px' }}>No tasks here</p>
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {filtered.map(task => (
            <div key={task.id} style={{
              backgroundColor: 'var(--white)',
              borderRadius: '12px',
              padding: '14px 16px',
              display: 'flex',
              alignItems: 'flex-start',
              gap: '12px',
              opacity: task.completed ? 0.5 : 1,
              transition: 'opacity 0.2s',
            }}>
              {/* Checkbox */}
              <button onClick={() => toggleComplete(task.id)} style={{
                width: '22px',
                height: '22px',
                borderRadius: '50%',
                border: '1.5px solid',
                borderColor: task.completed ? 'var(--accent)' : 'var(--border)',
                backgroundColor: task.completed ? 'var(--accent)' : 'transparent',
                cursor: 'pointer',
                flexShrink: 0,
                marginTop: '2px',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                color: 'var(--white)',
                fontSize: '12px',
              }}>{task.completed ? '✓' : ''}</button>

              {/* Content */}
              <div style={{ flex: 1, minWidth: 0 }} onClick={() => openEdit(task)}>
                <p style={{
                  fontSize: '15px',
                  fontWeight: '500',
                  textDecoration: task.completed ? 'line-through' : 'none',
                  marginBottom: '4px',
                  color: 'var(--text-primary)',
                }}>{task.title}</p>
                {task.notes ? (
                  <p style={{ fontSize: '12px', color: 'var(--text-secondary)', marginBottom: '6px' }}>{task.notes}</p>
                ) : null}
                <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', alignItems: 'center' }}>
                  {task.dueDate && (
                    <span style={{ fontSize: '11px', color: isToday(task.dueDate) ? '#B85C5C' : 'var(--text-secondary)' }}>
                      📅 {formatDate(task.dueDate)}
                    </span>
                  )}
                  <span style={{
                    fontSize: '10px',
                    padding: '2px 8px',
                    borderRadius: '10px',
                    backgroundColor: priorityColor[task.priority] + '22',
                    color: priorityColor[task.priority],
                    fontWeight: '600',
                  }}>{task.priority}</span>
                  <span style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>{task.category}</span>
                </div>
              </div>

              {/* Delete */}
              <button onClick={() => setShowDeleteConfirm(task.id)} style={{
                background: 'none',
                border: 'none',
                color: 'var(--border)',
                fontSize: '16px',
                cursor: 'pointer',
                padding: '0',
                flexShrink: 0,
              }}>✕</button>
            </div>
          ))}
        </div>
      )}

      {/* Floating action button */}
      <button onClick={openCreate} style={{
        position: 'fixed',
        bottom: 'calc(var(--nav-height) + 20px)',
        right: '24px',
        width: '52px',
        height: '52px',
        borderRadius: '50%',
        backgroundColor: 'var(--accent)',
        color: 'var(--white)',
        fontSize: '26px',
        border: 'none',
        cursor: 'pointer',
        boxShadow: '0 4px 16px rgba(160, 133, 108, 0.4)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
      }}>+</button>

      {/* Delete confirmation */}
      {showDeleteConfirm && (
        <div style={{
          position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)',
          display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200,
        }}>
          <div style={{
            backgroundColor: 'var(--white)', borderRadius: '20px 20px 0 0',
            padding: '28px 24px', width: '100%', maxWidth: '390px',
          }}>
            <h3 style={{ fontWeight: '500', marginBottom: '8px' }}>Delete task?</h3>
            <p style={{ color: 'var(--text-secondary)', fontSize: '14px', marginBottom: '24px' }}>This cannot be undone.</p>
            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowDeleteConfirm(null)} style={{
                flex: 1, padding: '14px', borderRadius: '12px', border: '1px solid var(--border)',
                backgroundColor: 'transparent', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer',
              }}>Cancel</button>
              <button onClick={() => deleteTask(showDeleteConfirm)} style={{
                flex: 1, padding: '14px', borderRadius: '12px', border: 'none',
                backgroundColor: 'var(--danger)', color: 'var(--white)',
                fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer',
              }}>Delete</button>
            </div>
          </div>
        </div>
      )}

      {/* Create / Edit modal */}
      {showModal && (
        <div style={{
          position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)',
          display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200,
        }}>
          <div style={{
            backgroundColor: 'var(--bg)', borderRadius: '20px 20px 0 0',
            padding: '28px 24px', width: '100%', maxWidth: '390px',
            maxHeight: '90vh', overflowY: 'auto',
          }}>
            <h3 style={{ fontWeight: '500', marginBottom: '24px', fontSize: '18px' }}>
              {editingId ? 'Edit Task' : 'New Task'}
            </h3>

            {/* Title */}
            <label style={labelStyle}>TITLE</label>
            <input
              value={form.title}
              onChange={e => setForm({ ...form, title: e.target.value })}
              placeholder="What needs to be done?"
              style={inputStyle}
            />

            {/* Notes */}
            <label style={labelStyle}>NOTES</label>
            <textarea
              value={form.notes}
              onChange={e => setForm({ ...form, notes: e.target.value })}
              placeholder="Any extra details..."
              rows={3}
              style={{ ...inputStyle, resize: 'none' }}
            />

            {/* Due date */}
            <label style={labelStyle}>DUE DATE</label>
            <input
              type="date"
              value={form.dueDate}
              onChange={e => setForm({ ...form, dueDate: e.target.value })}
              style={inputStyle}
            />

            {/* Priority */}
            <label style={labelStyle}>PRIORITY</label>
            <div style={{ display: 'flex', gap: '8px', marginBottom: '20px' }}>
              {PRIORITIES.map(p => (
                <button key={p} onClick={() => setForm({ ...form, priority: p })} style={{
                  flex: 1, padding: '10px', borderRadius: '10px',
                  border: '1.5px solid',
                  borderColor: form.priority === p ? priorityColor[p] : 'var(--border)',
                  backgroundColor: form.priority === p ? priorityColor[p] + '22' : 'transparent',
                  color: form.priority === p ? priorityColor[p] : 'var(--text-secondary)',
                  fontFamily: 'Jost, sans-serif', fontSize: '12px', fontWeight: '600',
                  cursor: 'pointer',
                }}>{p}</button>
              ))}
            </div>

            {/* Category */}
            <label style={labelStyle}>CATEGORY</label>
            <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', marginBottom: '28px' }}>
              {CATEGORIES.map(c => (
                <button key={c} onClick={() => setForm({ ...form, category: c })} style={{
                  padding: '8px 14px', borderRadius: '20px',
                  border: '1px solid',
                  borderColor: form.category === c ? 'var(--accent)' : 'var(--border)',
                  backgroundColor: form.category === c ? 'var(--accent)' : 'transparent',
                  color: form.category === c ? 'var(--white)' : 'var(--text-secondary)',
                  fontFamily: 'Jost, sans-serif', fontSize: '12px',
                  cursor: 'pointer',
                }}>{c}</button>
              ))}
            </div>

            {/* Buttons */}
            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowModal(false)} style={{
                flex: 1, padding: '14px', borderRadius: '12px',
                border: '1px solid var(--border)', backgroundColor: 'transparent',
                fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer',
              }}>Cancel</button>
              <button onClick={saveTask} style={{
                flex: 1, padding: '14px', borderRadius: '12px',
                border: 'none', backgroundColor: 'var(--accent)', color: 'var(--white)',
                fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer',
              }}>{editingId ? 'Save Changes' : 'Add Task'}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const labelStyle = {
  display: 'block',
  fontSize: '11px',
  letterSpacing: '0.1em',
  color: 'var(--text-secondary)',
  marginBottom: '8px',
  fontWeight: '500',
};

const inputStyle = {
  width: '100%',
  padding: '12px 14px',
  borderRadius: '10px',
  border: '1px solid var(--border)',
  backgroundColor: 'var(--white)',
  fontFamily: 'Jost, sans-serif',
  fontSize: '14px',
  color: 'var(--text-primary)',
  marginBottom: '20px',
  outline: 'none',
};

export default Tasks;