const SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbz1jZm6URtcAjSyN1Mc7RIMkH9hxxq_EM5dFeyaMgK66SEKE1XYjb1loCcyXIBAZquc2w/exec';

export async function saveToSheet(sheetName, data) {
  try {
    await fetch(SCRIPT_URL, {
      method: 'POST',
      mode: 'no-cors',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ sheet: sheetName, data }),
    });
  } catch (e) {
    console.error('Save failed:', e);
  }
}

export async function loadFromSheet(sheetName) {
  try {
    const res = await fetch(`${SCRIPT_URL}?sheet=${sheetName}`);
    const data = await res.json();
    // Fix date fields that Google Sheets may have converted
    return data.map(row => {
      const fixed = {};
      Object.keys(row).forEach(key => {
        const val = row[key];
        // If it looks like a Google Sheets date serial or Date object string, convert it
        if (typeof val === 'string' && val.match(/^\d{4}-\d{2}-\d{2}/)) {
          fixed[key] = val.slice(0, 10);
        } else if (typeof val === 'number' && key.toLowerCase().includes('date') && val > 40000) {
          // Google Sheets date serial number — convert to ISO string
          const date = new Date((val - 25569) * 86400 * 1000);
          fixed[key] = date.toISOString().split('T')[0];
        } else {
          fixed[key] = val;
        }
      });
      return fixed;
    });
  } catch (e) {
    console.error('Load failed:', e);
    return null;
  }
}
