import React, { useState } from 'react';

const EXERCISE_TYPES = ['Strength', 'Cardio', 'Flexibility', 'Sport', 'Other'];
const MUSCLE_GROUPS = ['Full body', 'Upper body', 'Lower body', 'Core', 'Back', 'Chest', 'Arms', 'Legs', 'Glutes', 'Cardio'];

const emptyPlan = { title: '', type: 'Strength', muscleGroup: 'Full body', exercises: [], restDay: false, notes: '' };
const emptyExercise = { name: '', sets: '3', reps: '10', weight: '', unit: 'kg', notes: '' };
const emptyLog = { planId: null, date: new Date().toISOString().split('T')[0], exercises: [], duration: '', feeling: '3', notes: '' };

function formatDate(dateStr) {
  if (!dateStr) return '';
  return new Date(dateStr + 'T00:00:00').toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short' });
}

const FEELINGS = ['😴', '😐', '🙂', '💪', '🔥'];

function Workout({ workouts, setWorkouts, workoutLogs, setWorkoutLogs }) {
  const [activeTab, setActiveTab] = useState('plans');
  const [showPlanModal, setShowPlanModal] = useState(false);
  const [showLogModal, setShowLogModal] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(null);
  const [planForm, setPlanForm] = useState(emptyPlan);
  const [logForm, setLogForm] = useState(emptyLog);
  const [exerciseForm, setExerciseForm] = useState(emptyExercise);
  const [editingId, setEditingId] = useState(null);
  const [selectedPlan, setSelectedPlan] = useState(null);
  const [logExercises, setLogExercises] = useState([]);

  function savePlan() {
    if (!planForm.title.trim()) return;
    if (editingId) {
      setWorkouts(workouts.map(w => w.id === editingId ? { ...w, ...planForm } : w));
    } else {
      setWorkouts([...workouts, { ...planForm, id: Date.now() }]);
    }
    setShowPlanModal(false);
    setEditingId(null);
  }

  function addExerciseToPlan() {
    if (!exerciseForm.name.trim()) return;
    setPlanForm({ ...planForm, exercises: [...planForm.exercises, { ...exerciseForm, id: Date.now() }] });
    setExerciseForm(emptyExercise);
  }

  function removeExerciseFromPlan(id) {
    setPlanForm({ ...planForm, exercises: planForm.exercises.filter(e => e.id !== id) });
  }

  function startLog(plan) {
    setLogExercises(plan.exercises.map(e => ({ ...e, completedSets: [] })));
    setLogForm({ ...emptyLog, planId: plan.id, date: new Date().toISOString().split('T')[0] });
    setSelectedPlan(plan);
    setShowLogModal(true);
  }

  function toggleSet(exId, setIndex) {
    setLogExercises(logExercises.map(ex => {
      if (ex.id !== exId) return ex;
      const sets = ex.completedSets.includes(setIndex)
        ? ex.completedSets.filter(s => s !== setIndex)
        : [...ex.completedSets, setIndex];
      return { ...ex, completedSets: sets };
    }));
  }

  function saveLog() {
    setWorkoutLogs([...workoutLogs, { ...logForm, id: Date.now(), exercises: logExercises, planTitle: selectedPlan?.title }]);
    setShowLogModal(false);
    setSelectedPlan(null);
  }

  function deleteItem(type, id) {
    if (type === 'plan') setWorkouts(workouts.filter(w => w.id !== id));
    if (type === 'log') setWorkoutLogs(workoutLogs.filter(l => l.id !== id));
    setShowDeleteConfirm(null);
  }

  // Progress stats
  const totalSessions = workoutLogs.length;
  const thisWeek = workoutLogs.filter(l => {
    const d = new Date(l.date);
    const now = new Date();
    const monday = new Date(now);
    monday.setDate(now.getDate() - ((now.getDay() + 6) % 7));
    monday.setHours(0, 0, 0, 0);
    return d >= monday;
  }).length;

  const typeColors = { Strength: '#7A8FA6', Cardio: '#B85C5C', Flexibility: '#7A9E87', Sport: '#C4A035', Other: '#A0856C' };

  return (
    <div style={{ padding: '32px 24px 24px', minHeight: '100vh', backgroundColor: 'var(--bg)' }}>
      <p style={{ color: 'var(--text-secondary)', fontSize: '13px', letterSpacing: '0.1em' }}>TRAIN</p>
      <h1 style={{ fontSize: '28px', fontWeight: '300', marginTop: '4px', marginBottom: '20px' }}>Workout</h1>

      {/* Stats */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '10px', marginBottom: '20px' }}>
        {[
          { label: 'Total sessions', value: totalSessions },
          { label: 'This week', value: thisWeek },
          { label: 'Plans', value: workouts.length },
        ].map(s => (
          <div key={s.label} style={{ backgroundColor: 'var(--white)', borderRadius: '12px', padding: '12px', textAlign: 'center' }}>
            <p style={{ fontSize: '22px', fontWeight: '300', color: 'var(--accent)' }}>{s.value}</p>
            <p style={{ fontSize: '10px', color: 'var(--text-secondary)', letterSpacing: '0.05em' }}>{s.label.toUpperCase()}</p>
          </div>
        ))}
      </div>

      {/* Tabs */}
      <div style={{ display: 'flex', gap: '8px', marginBottom: '24px' }}>
        {['plans', 'log', 'progress'].map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} style={{
            padding: '6px 14px', borderRadius: '20px', border: '1px solid',
            borderColor: activeTab === tab ? 'var(--accent)' : 'var(--border)',
            backgroundColor: activeTab === tab ? 'var(--accent)' : 'transparent',
            color: activeTab === tab ? 'var(--white)' : 'var(--text-secondary)',
            fontSize: '12px', fontFamily: 'Jost, sans-serif', fontWeight: '500',
            letterSpacing: '0.05em', cursor: 'pointer', textTransform: 'uppercase',
          }}>{tab}</button>
        ))}
      </div>

      {/* PLANS TAB */}
      {activeTab === 'plans' && (
        <div>
          {workouts.length === 0 ? (
            <div style={{ textAlign: 'center', marginTop: '40px', color: 'var(--text-secondary)' }}>
              <p style={{ fontSize: '32px', marginBottom: '12px' }}>◉</p>
              <p style={{ fontSize: '14px' }}>No workout plans yet</p>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
              {workouts.map(plan => (
                <div key={plan.id} style={{ backgroundColor: 'var(--white)', borderRadius: '14px', padding: '16px', borderLeft: `4px solid ${typeColors[plan.type] || 'var(--accent)'}` }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '8px' }}>
                    <div style={{ flex: 1 }}>
                      <p style={{ fontSize: '15px', fontWeight: '500', marginBottom: '2px' }}>{plan.title}</p>
                      <p style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>{plan.type} · {plan.muscleGroup} · {plan.exercises.length} exercises</p>
                    </div>
                    <div style={{ display: 'flex', gap: '8px' }}>
                      <button onClick={() => { setPlanForm({ title: plan.title, type: plan.type, muscleGroup: plan.muscleGroup, exercises: plan.exercises, restDay: plan.restDay, notes: plan.notes || '' }); setEditingId(plan.id); setShowPlanModal(true); }} style={{ background: 'none', border: 'none', color: 'var(--text-secondary)', fontSize: '14px', cursor: 'pointer' }}>✎</button>
                      <button onClick={() => setShowDeleteConfirm({ type: 'plan', id: plan.id })} style={{ background: 'none', border: 'none', color: 'var(--border)', fontSize: '16px', cursor: 'pointer' }}>✕</button>
                    </div>
                  </div>
                  {plan.exercises.length > 0 && (
                    <div style={{ marginBottom: '12px' }}>
                      {plan.exercises.slice(0, 3).map(ex => (
                        <p key={ex.id} style={{ fontSize: '12px', color: 'var(--text-secondary)', marginBottom: '2px' }}>· {ex.name} — {ex.sets}×{ex.reps}{ex.weight ? ` @ ${ex.weight}${ex.unit}` : ''}</p>
                      ))}
                      {plan.exercises.length > 3 && <p style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>+{plan.exercises.length - 3} more</p>}
                    </div>
                  )}
                  <button onClick={() => startLog(plan)} style={{
                    width: '100%', padding: '10px', borderRadius: '10px', border: 'none',
                    backgroundColor: typeColors[plan.type] || 'var(--accent)', color: 'var(--white)',
                    fontFamily: 'Jost, sans-serif', fontSize: '13px', cursor: 'pointer',
                  }}>Start workout →</button>
                </div>
              ))}
            </div>
          )}
          <button onClick={() => { setPlanForm(emptyPlan); setEditingId(null); setExerciseForm(emptyExercise); setShowPlanModal(true); }} style={{
            position: 'fixed', bottom: 'calc(var(--nav-height) + 20px)', right: '24px',
            width: '52px', height: '52px', borderRadius: '50%',
            backgroundColor: 'var(--accent)', color: 'var(--white)', fontSize: '26px',
            border: 'none', cursor: 'pointer', boxShadow: '0 4px 16px rgba(160, 133, 108, 0.4)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
          }}>+</button>
        </div>
      )}

      {/* LOG TAB */}
      {activeTab === 'log' && (
        <div>
          {workoutLogs.length === 0 ? (
            <div style={{ textAlign: 'center', marginTop: '40px', color: 'var(--text-secondary)' }}>
              <p style={{ fontSize: '32px', marginBottom: '12px' }}>📋</p>
              <p style={{ fontSize: '14px' }}>No sessions logged yet</p>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
              {[...workoutLogs].sort((a, b) => b.date.localeCompare(a.date)).map(log => (
                <div key={log.id} style={{ backgroundColor: 'var(--white)', borderRadius: '14px', padding: '14px 16px' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                    <div style={{ flex: 1 }}>
                      <p style={{ fontSize: '14px', fontWeight: '500', marginBottom: '2px' }}>{log.planTitle || 'Workout'}</p>
                      <p style={{ fontSize: '12px', color: 'var(--text-secondary)', marginBottom: '4px' }}>
                        {formatDate(log.date)}{log.duration ? ` · ${log.duration} min` : ''} · {FEELINGS[parseInt(log.feeling) - 1]}
                      </p>
                      <p style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>{log.exercises.length} exercises</p>
                      {log.notes && <p style={{ fontSize: '12px', color: 'var(--text-secondary)', marginTop: '4px' }}>{log.notes}</p>}
                    </div>
                    <button onClick={() => setShowDeleteConfirm({ type: 'log', id: log.id })} style={{ background: 'none', border: 'none', color: 'var(--border)', fontSize: '16px', cursor: 'pointer' }}>✕</button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* PROGRESS TAB */}
      {activeTab === 'progress' && (
        <div>
          {workoutLogs.length === 0 ? (
            <p style={{ color: 'var(--text-secondary)', fontSize: '14px', textAlign: 'center', marginTop: '40px' }}>Log some sessions to see your progress</p>
          ) : (
            <div>
              {/* Weekly activity */}
              <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '12px' }}>SESSIONS PER WEEK</p>
              <div style={{ backgroundColor: 'var(--white)', borderRadius: '14px', padding: '16px', marginBottom: '16px' }}>
                {Array.from({ length: 4 }, (_, weekIndex) => {
                  const weekEnd = new Date();
                  weekEnd.setDate(weekEnd.getDate() - weekIndex * 7);
                  const weekStart = new Date(weekEnd);
                  weekStart.setDate(weekEnd.getDate() - 6);
                  const count = workoutLogs.filter(l => {
                    const d = new Date(l.date);
                    return d >= weekStart && d <= weekEnd;
                  }).length;
                  const label = weekIndex === 0 ? 'This week' : `${weekIndex}w ago`;
                  return (
                    <div key={weekIndex} style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '10px' }}>
                      <span style={{ fontSize: '11px', color: 'var(--text-secondary)', width: '60px' }}>{label}</span>
                      <div style={{ flex: 1, height: '8px', backgroundColor: 'var(--surface)', borderRadius: '4px' }}>
                        <div style={{ height: '100%', borderRadius: '4px', width: `${Math.min(100, count / 7 * 100)}%`, backgroundColor: 'var(--accent)', transition: 'width 0.3s' }} />
                      </div>
                      <span style={{ fontSize: '12px', fontWeight: '600', color: 'var(--accent)', width: '20px' }}>{count}</span>
                    </div>
                  );
                })}
              </div>

              {/* Personal records */}
              <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '12px' }}>EXERCISE RECORDS</p>
              <div style={{ backgroundColor: 'var(--white)', borderRadius: '14px', padding: '16px' }}>
                {(() => {
                  const records = {};
                  workoutLogs.forEach(log => {
                    log.exercises.forEach(ex => {
                      const weight = parseFloat(ex.weight);
                      if (!weight) return;
                      if (!records[ex.name] || weight > records[ex.name]) {
                        records[ex.name] = weight;
                      }
                    });
                  });
                  const entries = Object.entries(records);
                  if (entries.length === 0) return <p style={{ fontSize: '13px', color: 'var(--text-secondary)' }}>No weight data yet</p>;
                  return entries.map(([name, weight]) => (
                    <div key={name} style={{ display: 'flex', justifyContent: 'space-between', paddingBottom: '8px', marginBottom: '8px', borderBottom: '1px solid var(--surface)' }}>
                      <span style={{ fontSize: '13px' }}>{name}</span>
                      <span style={{ fontSize: '13px', fontWeight: '600', color: 'var(--accent)' }}>{weight} kg PR</span>
                    </div>
                  ));
                })()}
              </div>
            </div>
          )}
        </div>
      )}

      {/* Delete confirm */}
      {showDeleteConfirm && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--white)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '8px' }}>Delete this?</h3>
            <p style={{ color: 'var(--text-secondary)', fontSize: '14px', marginBottom: '24px' }}>This cannot be undone.</p>
            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowDeleteConfirm(null)} style={cancelBtnStyle}>Cancel</button>
              <button onClick={() => deleteItem(showDeleteConfirm.type, showDeleteConfirm.id)} style={deleteBtnStyle}>Delete</button>
            </div>
          </div>
        </div>
      )}

      {/* Plan modal */}
      {showPlanModal && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--bg)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px', maxHeight: '90vh', overflowY: 'auto' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '24px', fontSize: '18px' }}>{editingId ? 'Edit Plan' : 'New Workout Plan'}</h3>

            <label style={labelStyle}>PLAN NAME</label>
            <input value={planForm.title} onChange={e => setPlanForm({ ...planForm, title: e.target.value })} placeholder="e.g. Push day, Leg day" style={inputStyle} />

            <label style={labelStyle}>TYPE</label>
            <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', marginBottom: '20px' }}>
              {EXERCISE_TYPES.map(t => (
                <button key={t} onClick={() => setPlanForm({ ...planForm, type: t })} style={{
                  padding: '6px 12px', borderRadius: '20px', border: '1px solid',
                  borderColor: planForm.type === t ? (typeColors[t] || 'var(--accent)') : 'var(--border)',
                  backgroundColor: planForm.type === t ? (typeColors[t] || 'var(--accent)') : 'transparent',
                  color: planForm.type === t ? 'var(--white)' : 'var(--text-secondary)',
                  fontFamily: 'Jost, sans-serif', fontSize: '12px', cursor: 'pointer',
                }}>{t}</button>
              ))}
            </div>

            <label style={labelStyle}>MUSCLE GROUP</label>
            <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap', marginBottom: '20px' }}>
              {MUSCLE_GROUPS.map(m => (
                <button key={m} onClick={() => setPlanForm({ ...planForm, muscleGroup: m })} style={{
                  padding: '5px 10px', borderRadius: '20px', border: '1px solid',
                  borderColor: planForm.muscleGroup === m ? 'var(--accent)' : 'var(--border)',
                  backgroundColor: planForm.muscleGroup === m ? 'var(--accent)' : 'transparent',
                  color: planForm.muscleGroup === m ? 'var(--white)' : 'var(--text-secondary)',
                  fontFamily: 'Jost, sans-serif', fontSize: '11px', cursor: 'pointer',
                }}>{m}</button>
              ))}
            </div>

            <label style={labelStyle}>EXERCISES</label>
            {planForm.exercises.map(ex => (
              <div key={ex.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '8px 12px', backgroundColor: 'var(--white)', borderRadius: '8px', marginBottom: '6px' }}>
                <div>
                  <span style={{ fontSize: '13px', fontWeight: '500' }}>{ex.name}</span>
                  <span style={{ fontSize: '12px', color: 'var(--text-secondary)', marginLeft: '8px' }}>{ex.sets}×{ex.reps}{ex.weight ? ` @ ${ex.weight}${ex.unit}` : ''}</span>
                </div>
                <button onClick={() => removeExerciseFromPlan(ex.id)} style={{ background: 'none', border: 'none', color: 'var(--border)', fontSize: '16px', cursor: 'pointer' }}>✕</button>
              </div>
            ))}

            <div style={{ backgroundColor: 'var(--white)', borderRadius: '12px', padding: '14px', marginBottom: '20px' }}>
              <p style={{ fontSize: '12px', color: 'var(--text-secondary)', marginBottom: '10px', letterSpacing: '0.05em' }}>ADD EXERCISE</p>
              <input value={exerciseForm.name} onChange={e => setExerciseForm({ ...exerciseForm, name: e.target.value })} placeholder="Exercise name" style={{ ...inputStyle, marginBottom: '8px' }} />
              <div style={{ display: 'flex', gap: '8px', marginBottom: '8px' }}>
                <div style={{ flex: 1 }}>
                  <label style={{ ...labelStyle, marginBottom: '4px' }}>SETS</label>
                  <input type="number" value={exerciseForm.sets} onChange={e => setExerciseForm({ ...exerciseForm, sets: e.target.value })} style={{ ...inputStyle, marginBottom: 0 }} />
                </div>
                <div style={{ flex: 1 }}>
                  <label style={{ ...labelStyle, marginBottom: '4px' }}>REPS</label>
                  <input type="number" value={exerciseForm.reps} onChange={e => setExerciseForm({ ...exerciseForm, reps: e.target.value })} style={{ ...inputStyle, marginBottom: 0 }} />
                </div>
                <div style={{ flex: 1 }}>
                  <label style={{ ...labelStyle, marginBottom: '4px' }}>WEIGHT</label>
                  <input type="number" value={exerciseForm.weight} onChange={e => setExerciseForm({ ...exerciseForm, weight: e.target.value })} placeholder="0" style={{ ...inputStyle, marginBottom: 0 }} />
                </div>
              </div>
              <button onClick={addExerciseToPlan} style={{ width: '100%', padding: '10px', borderRadius: '10px', border: 'none', backgroundColor: 'var(--surface)', color: 'var(--text-primary)', fontFamily: 'Jost, sans-serif', fontSize: '13px', cursor: 'pointer', marginTop: '8px' }}>+ Add exercise</button>
            </div>

            <label style={labelStyle}>NOTES</label>
            <textarea value={planForm.notes} onChange={e => setPlanForm({ ...planForm, notes: e.target.value })} placeholder="Optional notes" rows={3} style={{ ...inputStyle, resize: 'none' }} />

            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowPlanModal(false)} style={cancelBtnStyle}>Cancel</button>
              <button onClick={savePlan} style={saveBtnStyle}>{editingId ? 'Save Changes' : 'Save Plan'}</button>
            </div>
          </div>
        </div>
      )}

      {/* Log workout modal */}
      {showLogModal && selectedPlan && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--bg)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px', maxHeight: '90vh', overflowY: 'auto' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '4px', fontSize: '18px' }}>{selectedPlan.title}</h3>
            <p style={{ fontSize: '13px', color: 'var(--text-secondary)', marginBottom: '24px' }}>Log your session</p>

            {logExercises.map(ex => (
              <div key={ex.id} style={{ backgroundColor: 'var(--white)', borderRadius: '12px', padding: '14px', marginBottom: '10px' }}>
                <p style={{ fontSize: '14px', fontWeight: '500', marginBottom: '8px' }}>{ex.name}</p>
                <p style={{ fontSize: '12px', color: 'var(--text-secondary)', marginBottom: '10px' }}>Target: {ex.sets}×{ex.reps}{ex.weight ? ` @ ${ex.weight}${ex.unit}` : ''}</p>
                <div style={{ display: 'flex', gap: '8px' }}>
                  {Array.from({ length: parseInt(ex.sets) || 3 }, (_, i) => (
                    <button key={i} onClick={() => toggleSet(ex.id, i)} style={{
                      width: '36px', height: '36px', borderRadius: '50%', border: '1.5px solid',
                      borderColor: ex.completedSets.includes(i) ? 'var(--accent)' : 'var(--border)',
                      backgroundColor: ex.completedSets.includes(i) ? 'var(--accent)' : 'transparent',
                      color: ex.completedSets.includes(i) ? 'var(--white)' : 'var(--text-secondary)',
                      fontFamily: 'Jost, sans-serif', fontSize: '12px', cursor: 'pointer',
                    }}>{i + 1}</button>
                  ))}
                </div>
              </div>
            ))}

            <label style={labelStyle}>DURATION (minutes)</label>
            <input type="number" value={logForm.duration} onChange={e => setLogForm({ ...logForm, duration: e.target.value })} placeholder="e.g. 45" style={inputStyle} />

            <label style={labelStyle}>HOW DID IT FEEL?</label>
            <div style={{ display: 'flex', gap: '10px', marginBottom: '20px' }}>
              {FEELINGS.map((f, i) => (
                <button key={i} onClick={() => setLogForm({ ...logForm, feeling: String(i + 1) })} style={{
                  flex: 1, padding: '10px', borderRadius: '10px', border: '1.5px solid',
                  borderColor: logForm.feeling === String(i + 1) ? 'var(--accent)' : 'var(--border)',
                  backgroundColor: logForm.feeling === String(i + 1) ? 'var(--accent)' + '22' : 'transparent',
                  fontSize: '20px', cursor: 'pointer',
                }}>{f}</button>
              ))}
            </div>

            <label style={labelStyle}>NOTES</label>
            <textarea value={logForm.notes} onChange={e => setLogForm({ ...logForm, notes: e.target.value })} placeholder="How was the session?" rows={3} style={{ ...inputStyle, resize: 'none' }} />

            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowLogModal(false)} style={cancelBtnStyle}>Cancel</button>
              <button onClick={saveLog} style={saveBtnStyle}>Save Session</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const labelStyle = { display: 'block', fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '8px', fontWeight: '500' };
const inputStyle = { width: '100%', padding: '12px 14px', borderRadius: '10px', border: '1px solid var(--border)', backgroundColor: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '14px', color: 'var(--text-primary)', marginBottom: '20px', outline: 'none' };
const cancelBtnStyle = { flex: 1, padding: '14px', borderRadius: '12px', border: '1px solid var(--border)', backgroundColor: 'transparent', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer' };
