import React, { useState } from 'react';
import { BrowserRouter, Routes, Route, NavLink, useLocation, useNavigate } from 'react-router-dom';
import './index.css';
import { saveToSheet, loadFromSheet } from './sync';

import Home from './pages/Home';
import Tasks from './pages/Tasks';
import Habits from './pages/Habits';
import Finance from './pages/Finance';
import Meals from './pages/Meals';
import Outfit from './pages/Outfit';
import Settings from './pages/Settings';
import Work from './pages/Work';
import Workout from './pages/Workout';
import Relations from './pages/Relations';
import Calendar from './pages/Calendar';

function AppContent() {
  const [tasks, setTasks] = useState([]);
  const [habits, setHabits] = useState([]);
  const [transactions, setTransactions] = useState([]);
  const [budgets, setBudgets] = useState({});
  const [savings, setSavings] = useState([]);
  const [recipes, setRecipes] = useState([]);
  const [mealPlanner, setMealPlanner] = useState({});
  const [wardrobe, setWardrobe] = useState([]);
  const [outfitPlanner, setOutfitPlanner] = useState({});
  const [shifts, setShifts] = useState([]);
  const [workTasks, setWorkTasks] = useState([]);
  const [meetings, setMeetings] = useState([]);
  const [workouts, setWorkouts] = useState([]);
  const [workoutLogs, setWorkoutLogs] = useState([]);
  const [relations, setRelations] = useState([]);
  const [settings, setSettings] = useState({
    name: 'Salma',
    calorieGoal: 2000,
    proteinGoal: 50,
    carbsGoal: 260,
    fatGoal: 65,
    fiberGoal: 25,
    sugarGoal: 50,
    saltGoal: 6,
    workoutGoal: 3,
    currency: 'DKK',
    theme: 'warm',
    weekStartsOn: 'Monday',
  });
  const [events, setEvents] = useState([]);
  const [showMore, setShowMore] = useState(false);
  const [syncing, setSyncing] = useState(true);
  const location = useLocation();

  // Load all data on startup
  React.useEffect(() => {
    async function loadAll() {
      setSyncing(true);
      const [
        savedTasks, savedHabits, savedTransactions, savedBudgets,
        savedSavings, savedRecipes, savedMealPlanner, savedWardrobe,
        savedOutfitPlanner, savedShifts, savedWorkTasks, savedMeetings,
        savedWorkouts, savedWorkoutLogs, savedRelations, savedEvents,
        savedSettings,
      ] = await Promise.all([
        loadFromSheet('tasks'), loadFromSheet('habits'),
        loadFromSheet('transactions'), loadFromSheet('budgets'),
        loadFromSheet('savings'), loadFromSheet('recipes'),
        loadFromSheet('mealPlanner'), loadFromSheet('wardrobe'),
        loadFromSheet('outfitPlanner'), loadFromSheet('shifts'),
        loadFromSheet('workTasks'), loadFromSheet('meetings'),
        loadFromSheet('workouts'), loadFromSheet('workoutLogs'),
        loadFromSheet('relations'), loadFromSheet('events'),
        loadFromSheet('settings'),
      ]);
      if (savedTasks) setTasks(savedTasks.map(t => ({ ...t, dueDate: t.dueDate || '', logs: t.logs ? JSON.parse(t.logs) : undefined })));
      if (savedHabits) setHabits(savedHabits.map(h => ({ ...h, logs: h.logs ? JSON.parse(h.logs) : [] })));
      if (savedTransactions) setTransactions(savedTransactions.map(t => ({ ...t, amount: parseFloat(t.amount) })));
      if (savedBudgets) setBudgets(savedBudgets[0] ? JSON.parse(savedBudgets[0].data) : {});
      if (savedSavings) setSavings(savedSavings.map(s => ({ ...s, goal: parseFloat(s.goal), current: parseFloat(s.current) })));
      if (savedRecipes) setRecipes(savedRecipes.map(r => ({ ...r, ingredients: r.ingredients ? JSON.parse(r.ingredients) : [], tags: r.tags ? JSON.parse(r.tags) : [] })));
      if (savedMealPlanner) setMealPlanner(savedMealPlanner[0] ? JSON.parse(savedMealPlanner[0].data) : {});
      if (savedWardrobe) setWardrobe(savedWardrobe);
      if (savedOutfitPlanner) setOutfitPlanner(savedOutfitPlanner[0] ? JSON.parse(savedOutfitPlanner[0].data) : {});
      if (savedShifts) setShifts(savedShifts);
      if (savedWorkTasks) setWorkTasks(savedWorkTasks);
      if (savedMeetings) setMeetings(savedMeetings);
      if (savedWorkouts) setWorkouts(savedWorkouts.map(w => ({ ...w, exercises: w.exercises ? JSON.parse(w.exercises) : [] })));
      if (savedWorkoutLogs) setWorkoutLogs(savedWorkoutLogs.map(w => ({ ...w, exercises: w.exercises ? JSON.parse(w.exercises) : [] })));
      if (savedRelations) setRelations(savedRelations.map(r => ({ ...r, notes_log: r.notes_log ? JSON.parse(r.notes_log) : [], gifts: r.gifts ? JSON.parse(r.gifts) : [] })));
      if (savedEvents) setEvents(savedEvents);
      if (savedRelations) setRelations(savedRelations.map(r => ({ ...r, notes_log: r.notes_log ? JSON.parse(r.notes_log) : [], gifts: r.gifts ? JSON.parse(r.gifts) : [] })));
      if (savedSettings && savedSettings[0]) setSettings(s => ({ ...s, ...savedSettings[0] }));
      setSyncing(false);
    }
    loadAll();
  }, []);

  // Save whenever data changes
  React.useEffect(() => { if (!syncing) saveToSheet('tasks', tasks); }, [tasks]);
  React.useEffect(() => { if (!syncing) saveToSheet('habits', habits.map(h => ({ ...h, logs: JSON.stringify(h.logs) }))); }, [habits]);
  React.useEffect(() => { if (!syncing) saveToSheet('transactions', transactions); }, [transactions]);
  React.useEffect(() => { if (!syncing) saveToSheet('budgets', [{ data: JSON.stringify(budgets) }]); }, [budgets]);
  React.useEffect(() => { if (!syncing) saveToSheet('savings', savings); }, [savings]);
  React.useEffect(() => { if (!syncing) saveToSheet('recipes', recipes.map(r => ({ ...r, ingredients: JSON.stringify(r.ingredients), tags: JSON.stringify(r.tags) }))); }, [recipes]);
  React.useEffect(() => { if (!syncing) saveToSheet('mealPlanner', [{ data: JSON.stringify(mealPlanner) }]); }, [mealPlanner]);
  React.useEffect(() => { if (!syncing) saveToSheet('wardrobe', wardrobe); }, [wardrobe]);
  React.useEffect(() => { if (!syncing) saveToSheet('outfitPlanner', [{ data: JSON.stringify(outfitPlanner) }]); }, [outfitPlanner]);
  React.useEffect(() => { if (!syncing) saveToSheet('shifts', shifts); }, [shifts]);
  React.useEffect(() => { if (!syncing) saveToSheet('workTasks', workTasks); }, [workTasks]);
  React.useEffect(() => { if (!syncing) saveToSheet('meetings', meetings); }, [meetings]);
  React.useEffect(() => { if (!syncing) saveToSheet('workouts', workouts.map(w => ({ ...w, exercises: JSON.stringify(w.exercises) }))); }, [workouts]);
  React.useEffect(() => { if (!syncing) saveToSheet('workoutLogs', workoutLogs.map(w => ({ ...w, exercises: JSON.stringify(w.exercises) }))); }, [workoutLogs]);
  React.useEffect(() => { if (!syncing) saveToSheet('relations', relations.map(r => ({ ...r, notes_log: JSON.stringify(r.notes_log), gifts: JSON.stringify(r.gifts) }))); }, [relations]);
  React.useEffect(() => { if (!syncing) saveToSheet('events', events); }, [events]);
  React.useEffect(() => { if (!syncing) saveToSheet('settings', [settings]); }, [settings]);

  const mainNav = [
    { to: '/', label: 'Home', icon: '⌂', exact: true },
    { to: '/tasks', label: 'Tasks', icon: '✓' },
    { to: '/habits', label: 'Habits', icon: '◎' },
    { to: '/calendar', label: 'Calendar', icon: '▦' },
    { to: '/meals', label: 'Meals', icon: '❧' },
  ];

  const morePages = [
    { to: '/outfit', label: 'Outfit', icon: '◇' },
    { to: '/finance', label: 'Finance', icon: '◈' },
    { to: '/work', label: 'Work', icon: '⊞' },
    { to: '/workout', label: 'Workout', icon: '◉' },
    { to: '/relations', label: 'Relations', icon: '♡' },
    { to: '/settings', label: 'Settings', icon: '⚙' },
  ];

  return (
    <div>
      {syncing && (
        <div style={{
          position: 'fixed', top: 0, left: 0, right: 0,
          backgroundColor: 'var(--accent)', color: 'var(--white)',
          textAlign: 'center', padding: '6px',
          fontSize: '12px', letterSpacing: '0.1em', zIndex: 999,
        }}>SYNCING...</div>
      )}
      <div style={{ paddingBottom: 'var(--nav-height)' }}>
        <Routes>
        <Route path="/" element={
            <Home
              tasks={tasks}
              habits={habits}
              transactions={transactions}
              mealPlanner={mealPlanner}
              outfitPlanner={outfitPlanner}
              shifts={shifts}
              workouts={workoutLogs}
              events={events}
              relations={relations}
              settings={settings}
            />
          } />
          <Route path="/tasks" element={<Tasks tasks={tasks} setTasks={setTasks} />} />
          <Route path="/habits" element={<Habits habits={habits} setHabits={setHabits} />} />
          <Route path="/finance" element={<Finance transactions={transactions} setTransactions={setTransactions} budgets={budgets} setBudgets={setBudgets} savings={savings} setSavings={setSavings} />} />
          <Route path="/meals" element={<Meals recipes={recipes} setRecipes={setRecipes} planner={mealPlanner} setPlanner={setMealPlanner} />} />
          <Route path="/outfit" element={<Outfit wardrobe={wardrobe} setWardrobe={setWardrobe} outfitPlanner={outfitPlanner} setOutfitPlanner={setOutfitPlanner} />} />
          <Route path="/work" element={<Work shifts={shifts} setShifts={setShifts} workTasks={workTasks} setWorkTasks={setWorkTasks} meetings={meetings} setMeetings={setMeetings} />} />
          <Route path="/workout" element={<Workout workouts={workouts} setWorkouts={setWorkouts} workoutLogs={workoutLogs} setWorkoutLogs={setWorkoutLogs} />} />
          <Route path="/relations" element={<Relations relations={relations} setRelations={setRelations} />} />
          <Route path="/calendar" element={<Calendar tasks={tasks} shifts={shifts} workoutLogs={workoutLogs} events={events} setEvents={setEvents} relations={relations} mealPlanner={mealPlanner} recipes={recipes} />} />
          <Route path="/settings" element={<Settings settings={settings} setSettings={setSettings} />} />
        </Routes>
      </div>

      {/* Bottom nav */}
      <nav style={{
        position: 'fixed', bottom: 0, left: '50%', transform: 'translateX(-50%)',
        width: '100%', maxWidth: '390px', height: 'var(--nav-height)',
        backgroundColor: 'var(--white)', borderTop: '1px solid var(--border)',
        display: 'flex', alignItems: 'center', justifyContent: 'space-around', zIndex: 100,
      }}>
        {mainNav.map(item => (
          <NavLink key={item.to} to={item.to} end={item.exact} style={{ textDecoration: 'none', flex: 1, display: 'flex', justifyContent: 'center', padding: '8px 0' }}>
            {({ isActive }) => (
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '2px', color: isActive ? 'var(--accent)' : 'var(--text-secondary)', transition: 'color 0.2s' }}>
                <span style={{ fontSize: '18px' }}>{item.icon}</span>
                <span style={{ fontSize: '10px', fontWeight: isActive ? '600' : '400', letterSpacing: '0.05em' }}>{item.label.toUpperCase()}</span>
              </div>
            )}
          </NavLink>
        ))}

        {/* More button */}
        <button onClick={() => setShowMore(true)} style={{
          flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center',
          gap: '2px', background: 'none', border: 'none', cursor: 'pointer',
          color: morePages.some(p => location.pathname === p.to) ? 'var(--accent)' : 'var(--text-secondary)',
          padding: '8px 0',
        }}>
          <span style={{ fontSize: '18px' }}>···</span>
          <span style={{ fontSize: '10px', letterSpacing: '0.05em' }}>MORE</span>
        </button>
      </nav>

      {/* More menu overlay */}
      {showMore && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', zIndex: 200, display: 'flex', alignItems: 'flex-end', justifyContent: 'center' }}
          onClick={() => setShowMore(false)}>
          <div style={{ backgroundColor: 'var(--bg)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px' }}
            onClick={e => e.stopPropagation()}>
            <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '16px' }}>MORE PAGES</p>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '10px', marginBottom: '20px' }}>
              {morePages.map(page => (
                <NavLink key={page.to} to={page.to} onClick={() => setShowMore(false)}
                  style={{ textDecoration: 'none' }}>
                  {({ isActive }) => (
                    <div style={{
                      backgroundColor: isActive ? 'var(--accent)' : 'var(--white)',
                      borderRadius: '14px', padding: '16px 12px',
                      display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '6px',
                      border: '1px solid', borderColor: isActive ? 'var(--accent)' : 'var(--border)',
                    }}>
                      <span style={{ fontSize: '22px', color: isActive ? 'var(--white)' : 'var(--text-primary)' }}>{page.icon}</span>
                      <span style={{ fontSize: '11px', color: isActive ? 'var(--white)' : 'var(--text-secondary)', letterSpacing: '0.05em' }}>{page.label.toUpperCase()}</span>
                    </div>
                  )}
                </NavLink>
              ))}
            </div>
            <button onClick={() => setShowMore(false)} style={{
              width: '100%', padding: '14px', borderRadius: '12px',
              border: '1px solid var(--border)', backgroundColor: 'transparent',
              fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer',
            }}>Close</button>
          </div>
        </div>
      )}
    </div>
  );
}

function App() {
  return (
    <BrowserRouter>
      <AppContent />
    </BrowserRouter>
  );
}

export default App;