import React, { useState } from 'react';
import BarcodeScanner from './BarcodeScanner';

const UNITS = ['g', 'ml', 'dl', 'l', 'tsp', 'tbsp', 'cup', 'piece'];

const emptyIngredient = {
  name: '', amount: '', unit: 'g',
  per100g: { calories: 0, protein: 0, carbs: 0, fat: 0, fiber: 0, sugar: 0, salt: 0 },
};

const emptyRecipe = {
  title: '', description: '', servings: '2',
  tags: [], ingredients: [], instructions: '',
};

const TAGS = ['Breakfast', 'Lunch', 'Dinner', 'Snack', 'Vegetarian', 'Vegan', 'Quick', 'Meal prep'];

function calcNutrition(ingredients) {
  return ingredients.reduce((totals, ing) => {
    const factor = (parseFloat(ing.amount) || 0) / 100;
    Object.keys(totals).forEach(key => {
      totals[key] += (ing.per100g[key] || 0) * factor;
    });
    return totals;
  }, { calories: 0, protein: 0, carbs: 0, fat: 0, fiber: 0, sugar: 0, salt: 0 });
}

function RecipeLibrary({ recipes, setRecipes }) {
  const [view, setView] = useState('list');
  const [selectedRecipe, setSelectedRecipe] = useState(null);
  const [form, setForm] = useState(emptyRecipe);
  const [editingId, setEditingId] = useState(null);
  const [ingForm, setIngForm] = useState(emptyIngredient);
  const [showScanner, setShowScanner] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [manualLookup, setManualLookup] = useState('');
  const [lookupLoading, setLookupLoading] = useState(false);
  const [lookupError, setLookupError] = useState('');

  const filtered = recipes.filter(r =>
    r.title.toLowerCase().includes(searchQuery.toLowerCase())
  );

  function openCreate() {
    setForm(emptyRecipe);
    setEditingId(null);
    setIngForm(emptyIngredient);
    setView('create');
  }

  function openEdit(recipe) {
    setForm({
      title: recipe.title,
      description: recipe.description || '',
      servings: recipe.servings.toString(),
      tags: recipe.tags || [],
      ingredients: recipe.ingredients || [],
      instructions: recipe.instructions || '',
    });
    setEditingId(recipe.id);
    setIngForm(emptyIngredient);
    setView('create');
  }

  function saveRecipe() {
    if (!form.title.trim()) return;
    if (editingId) {
      setRecipes(recipes.map(r => r.id === editingId ? { ...r, ...form, servings: parseInt(form.servings) } : r));
    } else {
      setRecipes([...recipes, { ...form, id: Date.now(), servings: parseInt(form.servings) }]);
    }
    setView('list');
  }

  function deleteRecipe(id) {
    setRecipes(recipes.filter(r => r.id !== id));
    setShowDeleteConfirm(null);
    setView('list');
  }

  function addIngredient() {
    if (!ingForm.name.trim() || !ingForm.amount) return;
    setForm({ ...form, ingredients: [...form.ingredients, { ...ingForm, id: Date.now() }] });
    setIngForm(emptyIngredient);
    setLookupError('');
  }

  function removeIngredient(id) {
    setForm({ ...form, ingredients: form.ingredients.filter(i => i.id !== id) });
  }

  function toggleTag(tag) {
    const tags = form.tags.includes(tag)
      ? form.tags.filter(t => t !== tag)
      : [...form.tags, tag];
    setForm({ ...form, tags });
  }

  function handleScanResult(product) {
    setShowScanner(false);
    setIngForm({ ...ingForm, name: product.name, per100g: product.per100g });
  }

  async function lookupByName() {
    if (!manualLookup.trim()) return;
    setLookupLoading(true);
    setLookupError('');
    try {
      const res = await fetch(
        `https://world.openfoodfacts.org/cgi/search.pl?search_terms=${encodeURIComponent(manualLookup)}&action=process&json=true&page_size=1`
      );
      const data = await res.json();
      if (data.products && data.products.length > 0) {
        const p = data.products[0];
        const n = p.nutriments || {};
        setIngForm({
          ...ingForm,
          name: p.product_name || manualLookup,
          per100g: {
            calories: Math.round(n['energy-kcal_100g'] || 0),
            protein: Math.round((n['proteins_100g'] || 0) * 10) / 10,
            carbs: Math.round((n['carbohydrates_100g'] || 0) * 10) / 10,
            fat: Math.round((n['fat_100g'] || 0) * 10) / 10,
            fiber: Math.round((n['fiber_100g'] || 0) * 10) / 10,
            sugar: Math.round((n['sugars_100g'] || 0) * 10) / 10,
            salt: Math.round((n['salt_100g'] || 0) * 10) / 10,
          },
        });
        setManualLookup('');
      } else {
        setLookupError('Product not found. Try a different name.');
      }
    } catch (e) {
      setLookupError('Could not connect to OpenFoodFacts.');
    }
    setLookupLoading(false);
  }

  const nutrition = calcNutrition(form.ingredients);
  const servings = parseInt(form.servings) || 1;

  // LIST VIEW
  if (view === 'list') return (
    <div>
      <input
        value={searchQuery}
        onChange={e => setSearchQuery(e.target.value)}
        placeholder="Search recipes..."
        style={inputStyle}
      />
      {filtered.length === 0 ? (
        <p style={{ color: 'var(--text-secondary)', fontSize: '14px', textAlign: 'center', marginTop: '40px' }}>
          {recipes.length === 0 ? 'No recipes yet — add your first one' : 'No results'}
        </p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {filtered.map(recipe => {
            const nut = calcNutrition(recipe.ingredients || []);
            const perServing = Math.round(nut.calories / (recipe.servings || 1));
            return (
              <div key={recipe.id} style={{ backgroundColor: 'var(--white)', borderRadius: '14px', padding: '16px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                  <div style={{ flex: 1 }} onClick={() => { setSelectedRecipe(recipe); setView('detail'); }}>
                    <p style={{ fontSize: '15px', fontWeight: '500', marginBottom: '4px' }}>{recipe.title}</p>
                    <p style={{ fontSize: '12px', color: 'var(--text-secondary)', marginBottom: '6px' }}>
                      {recipe.ingredients.length} ingredients · {recipe.servings} servings · {perServing} kcal/serving
                    </p>
                    <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap' }}>
                      {(recipe.tags || []).map(tag => (
                        <span key={tag} style={{ fontSize: '10px', padding: '2px 8px', borderRadius: '10px', backgroundColor: 'var(--surface)', color: 'var(--text-secondary)' }}>{tag}</span>
                      ))}
                    </div>
                  </div>
                  <div style={{ display: 'flex', gap: '8px' }}>
                    <button onClick={() => openEdit(recipe)} style={{ background: 'none', border: 'none', color: 'var(--text-secondary)', fontSize: '14px', cursor: 'pointer' }}>✎</button>
                    <button onClick={() => setShowDeleteConfirm(recipe.id)} style={{ background: 'none', border: 'none', color: 'var(--border)', fontSize: '16px', cursor: 'pointer' }}>✕</button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      <button onClick={openCreate} style={{
        position: 'fixed', bottom: 'calc(var(--nav-height) + 20px)', right: '24px',
        width: '52px', height: '52px', borderRadius: '50%',
        backgroundColor: 'var(--accent)', color: 'var(--white)',
        fontSize: '26px', border: 'none', cursor: 'pointer',
        boxShadow: '0 4px 16px rgba(160, 133, 108, 0.4)',
        display: 'flex', alignItems: 'center', justifyContent: 'center',
      }}>+</button>

      {showDeleteConfirm && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--white)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '8px' }}>Delete recipe?</h3>
            <p style={{ color: 'var(--text-secondary)', fontSize: '14px', marginBottom: '24px' }}>This cannot be undone.</p>
            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowDeleteConfirm(null)} style={cancelBtnStyle}>Cancel</button>
              <button onClick={() => deleteRecipe(showDeleteConfirm)} style={deleteBtnStyle}>Delete</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );

  // DETAIL VIEW
  if (view === 'detail' && selectedRecipe) {
    const nut = calcNutrition(selectedRecipe.ingredients || []);
    const srv = selectedRecipe.servings || 1;
    return (
      <div>
        <button onClick={() => setView('list')} style={{ background: 'none', border: 'none', color: 'var(--accent)', fontSize: '14px', cursor: 'pointer', marginBottom: '16px', padding: 0 }}>← Back</button>
        <h2 style={{ fontSize: '22px', fontWeight: '400', marginBottom: '4px' }}>{selectedRecipe.title}</h2>
        <p style={{ fontSize: '13px', color: 'var(--text-secondary)', marginBottom: '12px' }}>{selectedRecipe.servings} servings</p>
        {selectedRecipe.description && <p style={{ fontSize: '14px', marginBottom: '16px', color: 'var(--text-secondary)' }}>{selectedRecipe.description}</p>}

        {/* Nutrition summary */}
        <div style={{ backgroundColor: 'var(--white)', borderRadius: '14px', padding: '16px', marginBottom: '16px' }}>
          <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '12px' }}>NUTRITION PER SERVING</p>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '8px' }}>
            {[
              { label: 'Calories', value: Math.round(nut.calories / srv), unit: 'kcal' },
              { label: 'Protein', value: Math.round(nut.protein / srv * 10) / 10, unit: 'g' },
              { label: 'Carbs', value: Math.round(nut.carbs / srv * 10) / 10, unit: 'g' },
              { label: 'Fat', value: Math.round(nut.fat / srv * 10) / 10, unit: 'g' },
            ].map(n => (
              <div key={n.label} style={{ textAlign: 'center' }}>
                <p style={{ fontSize: '16px', fontWeight: '600', color: 'var(--accent)' }}>{n.value}</p>
                <p style={{ fontSize: '10px', color: 'var(--text-secondary)' }}>{n.unit} {n.label}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Ingredients */}
        <div style={{ backgroundColor: 'var(--white)', borderRadius: '14px', padding: '16px', marginBottom: '16px' }}>
          <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '12px' }}>INGREDIENTS</p>
          {(selectedRecipe.ingredients || []).map(ing => (
            <div key={ing.id} style={{ display: 'flex', justifyContent: 'space-between', paddingBottom: '8px', marginBottom: '8px', borderBottom: '1px solid var(--surface)' }}>
              <span style={{ fontSize: '13px' }}>{ing.name}</span>
              <span style={{ fontSize: '13px', color: 'var(--text-secondary)' }}>{ing.amount}{ing.unit}</span>
            </div>
          ))}
        </div>

        {/* Instructions */}
        {selectedRecipe.instructions && (
          <div style={{ backgroundColor: 'var(--white)', borderRadius: '14px', padding: '16px', marginBottom: '16px' }}>
            <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '12px' }}>INSTRUCTIONS</p>
            <p style={{ fontSize: '14px', lineHeight: '1.6', color: 'var(--text-primary)' }}>{selectedRecipe.instructions}</p>
          </div>
        )}

        <button onClick={() => openEdit(selectedRecipe)} style={{
          width: '100%', padding: '14px', borderRadius: '12px', border: '1px solid var(--border)',
          backgroundColor: 'transparent', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer',
        }}>Edit Recipe</button>
      </div>
    );
  }

  // CREATE / EDIT VIEW
  return (
    <div>
      {showScanner && <BarcodeScanner onResult={handleScanResult} onClose={() => setShowScanner(false)} />}

      <button onClick={() => setView('list')} style={{ background: 'none', border: 'none', color: 'var(--accent)', fontSize: '14px', cursor: 'pointer', marginBottom: '16px', padding: 0 }}>← Back</button>
      <h2 style={{ fontSize: '20px', fontWeight: '400', marginBottom: '24px' }}>{editingId ? 'Edit Recipe' : 'New Recipe'}</h2>

      <label style={labelStyle}>RECIPE NAME</label>
      <input value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder="e.g. Overnight oats" style={inputStyle} />

      <label style={labelStyle}>DESCRIPTION</label>
      <input value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} placeholder="Optional short description" style={inputStyle} />

      <label style={labelStyle}>SERVINGS</label>
      <input type="number" value={form.servings} onChange={e => setForm({ ...form, servings: e.target.value })} style={{ ...inputStyle, width: '100px' }} />

      <label style={labelStyle}>TAGS</label>
      <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap', marginBottom: '20px' }}>
        {TAGS.map(tag => (
          <button key={tag} onClick={() => toggleTag(tag)} style={{
            padding: '5px 12px', borderRadius: '20px', border: '1px solid',
            borderColor: form.tags.includes(tag) ? 'var(--accent)' : 'var(--border)',
            backgroundColor: form.tags.includes(tag) ? 'var(--accent)' : 'transparent',
            color: form.tags.includes(tag) ? 'var(--white)' : 'var(--text-secondary)',
            fontFamily: 'Jost, sans-serif', fontSize: '12px', cursor: 'pointer',
          }}>{tag}</button>
        ))}
      </div>

      {/* Ingredients section */}
      <label style={labelStyle}>INGREDIENTS</label>

      {form.ingredients.length > 0 && (
        <div style={{ marginBottom: '12px' }}>
          {form.ingredients.map(ing => (
            <div key={ing.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '8px 12px', backgroundColor: 'var(--white)', borderRadius: '8px', marginBottom: '6px' }}>
              <div>
                <span style={{ fontSize: '13px', fontWeight: '500' }}>{ing.name}</span>
                <span style={{ fontSize: '12px', color: 'var(--text-secondary)', marginLeft: '8px' }}>{ing.amount}{ing.unit}</span>
                <span style={{ fontSize: '11px', color: 'var(--text-secondary)', marginLeft: '8px' }}>{ing.per100g.calories} kcal/100g</span>
              </div>
              <button onClick={() => removeIngredient(ing.id)} style={{ background: 'none', border: 'none', color: 'var(--border)', fontSize: '16px', cursor: 'pointer' }}>✕</button>
            </div>
          ))}
        </div>
      )}

      {/* Nutrition live preview */}
      {form.ingredients.length > 0 && (
        <div style={{ backgroundColor: 'var(--surface)', borderRadius: '10px', padding: '12px', marginBottom: '16px' }}>
          <p style={{ fontSize: '11px', color: 'var(--text-secondary)', marginBottom: '8px', letterSpacing: '0.08em' }}>TOTAL PER SERVING ({servings} servings)</p>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '4px', textAlign: 'center' }}>
            {[
              { label: 'kcal', value: Math.round(nutrition.calories / servings) },
              { label: 'protein', value: `${Math.round(nutrition.protein / servings * 10) / 10}g` },
              { label: 'carbs', value: `${Math.round(nutrition.carbs / servings * 10) / 10}g` },
              { label: 'fat', value: `${Math.round(nutrition.fat / servings * 10) / 10}g` },
            ].map(n => (
              <div key={n.label}>
                <p style={{ fontSize: '14px', fontWeight: '600', color: 'var(--accent)' }}>{n.value}</p>
                <p style={{ fontSize: '10px', color: 'var(--text-secondary)' }}>{n.label}</p>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Add ingredient */}
      <div style={{ backgroundColor: 'var(--white)', borderRadius: '12px', padding: '14px', marginBottom: '20px' }}>
        <p style={{ fontSize: '12px', color: 'var(--text-secondary)', marginBottom: '10px', letterSpacing: '0.05em' }}>ADD INGREDIENT</p>

        {/* Lookup row */}
        <div style={{ display: 'flex', gap: '8px', marginBottom: '10px' }}>
          <input
            value={manualLookup}
            onChange={e => setManualLookup(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && lookupByName()}
            placeholder="Search OpenFoodFacts..."
            style={{ ...inputStyle, marginBottom: 0, flex: 1, fontSize: '13px', padding: '9px 12px' }}
          />
          <button onClick={lookupByName} disabled={lookupLoading} style={{
            padding: '9px 12px', borderRadius: '10px', border: 'none',
            backgroundColor: 'var(--accent)', color: 'var(--white)',
            fontFamily: 'Jost, sans-serif', fontSize: '12px', cursor: 'pointer', whiteSpace: 'nowrap',
          }}>{lookupLoading ? '...' : 'Search'}</button>
          <button onClick={() => setShowScanner(true)} style={{
            padding: '9px 12px', borderRadius: '10px', border: '1px solid var(--border)',
            backgroundColor: 'transparent', fontSize: '18px', cursor: 'pointer',
          }}>📷</button>
        </div>
        {lookupError && <p style={{ fontSize: '12px', color: 'var(--danger)', marginBottom: '8px' }}>{lookupError}</p>}

        <input value={ingForm.name} onChange={e => setIngForm({ ...ingForm, name: e.target.value })} placeholder="Ingredient name" style={{ ...inputStyle, marginBottom: '8px', fontSize: '13px' }} />

        {ingForm.per100g.calories > 0 && (
          <p style={{ fontSize: '11px', color: 'var(--accent)', marginBottom: '8px' }}>
            ✓ {ingForm.per100g.calories} kcal · {ingForm.per100g.protein}g protein · {ingForm.per100g.carbs}g carbs · {ingForm.per100g.fat}g fat per 100g
          </p>
        )}

        <div style={{ display: 'flex', gap: '8px', marginBottom: '10px' }}>
          <input type="number" value={ingForm.amount} onChange={e => setIngForm({ ...ingForm, amount: e.target.value })} placeholder="Amount" style={{ ...inputStyle, marginBottom: 0, flex: 1, fontSize: '13px', padding: '9px 12px' }} />
          <select value={ingForm.unit} onChange={e => setIngForm({ ...ingForm, unit: e.target.value })} style={{ ...inputStyle, marginBottom: 0, width: '80px', fontSize: '13px', padding: '9px 12px' }}>
            {UNITS.map(u => <option key={u}>{u}</option>)}
          </select>
        </div>

        <button onClick={addIngredient} style={{
          width: '100%', padding: '10px', borderRadius: '10px', border: 'none',
          backgroundColor: 'var(--surface)', color: 'var(--text-primary)',
          fontFamily: 'Jost, sans-serif', fontSize: '13px', cursor: 'pointer',
        }}>+ Add to recipe</button>
      </div>

      <label style={labelStyle}>INSTRUCTIONS</label>
      <textarea value={form.instructions} onChange={e => setForm({ ...form, instructions: e.target.value })}
        placeholder="Step by step instructions..." rows={5}
        style={{ ...inputStyle, resize: 'none' }} />

      <div style={{ display: 'flex', gap: '12px', marginBottom: '40px' }}>
        <button onClick={() => setView('list')} style={cancelBtnStyle}>Cancel</button>
        <button onClick={saveRecipe} style={saveBtnStyle}>{editingId ? 'Save Changes' : 'Save Recipe'}</button>
      </div>
    </div>
  );
}

const labelStyle = { display: 'block', fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '8px', fontWeight: '500' };
const inputStyle = { width: '100%', padding: '12px 14px', borderRadius: '10px', border: '1px solid var(--border)', backgroundColor: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '14px', color: 'var(--text-primary)', marginBottom: '20px', outline: 'none' };
const cancelBtnStyle = { flex: 1, padding: '14px', borderRadius: '12px', border: '1px solid var(--border)', backgroundColor: 'transparent', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer' };
const saveBtnStyle = { flex: 1, padding: '14px', borderRadius: '12px', border: 'none', backgroundColor: 'var(--accent)', color: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer' };
const deleteBtnStyle = { flex: 1, padding: '14px', borderRadius: '12px', border: 'none', backgroundColor: 'var(--danger)', color: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer' };

export default RecipeLibrary;